// TextDecoder cannot read directly from a SharedArrayBuffer view, so copy out first.
function toJsString(ptr, len, mem) {return new TextDecoder().decode(new Uint8Array(new Uint8Array(mem.buffer, ptr, len)));}
// TextEncoder.encodeInto cannot target a SharedArrayBuffer view, so encode to a
// temp buffer and copy in with .set (which does accept shared destinations).
function wasmStoreJsString(str, ptr, len, mem) {
	const encoded = new TextEncoder().encode(str);
	const n = Math.min(encoded.length, len);
	new Uint8Array(mem.buffer, ptr, n).set(encoded.subarray(0, n));
	return n;
}

// In-memory WASI filesystem. The wasm has no real disk, so the host preloads read files by
// name (initWasm fetches -play into fsReadFiles) and collects written bytes to download on
// close (-record). fd 3 is the sole "." preopen; open files get fds from fsNextFd up.
const fsReadFiles = {};   // name -> Uint8Array
const fsOpenFds = {};     // fd -> { name, data, offset } (read) | { name, write:true, chunks } (write)
let fsNextFd = 100;
let wasmArgs = ['main.wasm']; // argv handed to the wasm via WASI args_get; initWasm appends -play/-record

function downloadFile(name, bytes) {
	const a = document.createElement('a');
	a.href = URL.createObjectURL(new Blob([bytes]));
	a.download = name;
	a.click();
	URL.revokeObjectURL(a.href);
}

// A first load fetches several MB and compiles it, which on a phone can take long enough that a
// black page looks broken. Stages are named so a slow network is distinguishable from a slow
// compile. Nothing shows for the first half second, so a warm load stays a plain black screen.
let statusEl;
let statusTimer;

function setStatus(text) {
	if (text === null) {
		clearTimeout(statusTimer);
		if (statusEl)
			statusEl.remove();
		statusEl = undefined;
		return;
	}
	if (!statusEl) {
		statusEl = document.createElement('div');
		statusEl.style.cssText = 'position:fixed;left:0;right:0;top:50%;z-index:1;transform:translateY(-50%);'
			+ 'text-align:center;font:16px sans-serif;color:#c0c0c0;pointer-events:none;visibility:hidden;';
		document.body.appendChild(statusEl);
		statusTimer = setTimeout(() => { statusEl.style.visibility = 'visible'; }, 500);
	}
	statusEl.textContent = text;
}

// Counts bytes on the way through so the download reports progress, without giving up streaming
// compilation. The bytes counted here are decoded ones while content-length is the *compressed*
// size when the server encodes the response - so the total is only used for an identity encoding,
// and a compressed response reports a bare byte count instead of a total it would overshoot.
function fetchProgress(fileName) {
	return fetch(fileName).then((resp) => {
		if (!resp.ok || !resp.body)
			return resp;
		const mb = (bytes) => (bytes / 1048576).toFixed(1);
		const encoding = resp.headers.get('content-encoding');
		const total = (!encoding || encoding === 'identity') ? Number(resp.headers.get('content-length')) || 0 : 0;
		const reader = resp.body.getReader();
		let loaded = 0;
		const stream = new ReadableStream({
			pull: (c) => reader.read().then(({ done, value }) => {
				if (done)
					return c.close();
				loaded += value.length;
				setStatus(loaded <= total
					? 'downloading... ' + mb(loaded) + '/' + mb(total) + ' MB'
					: 'downloading... ' + mb(loaded) + ' MB');
				c.enqueue(value);
			}),
			cancel: (reason) => reader.cancel(reason),
		});
		return new Response(stream, { headers: resp.headers });
	});
}

async function loadWasm(fileName, imports, ctx) {
	setStatus('downloading...');
	const module = await WebAssembly.compileStreaming(fetchProgress(fileName));
	setStatus('instantiating...');
	return instantiateModuleAsync(module, imports, ctx);
}

function buildImportObject(imports, ctx) {
	// Shared memory lets the AudioWorklet thread re-instantiate over the same heap.
	// Only modules built with --import-memory consume it (initial/maximum must match
	// the wasm's --initial/--max-memory); others keep their own exported memory.
	// 4096 pages = 256 MB
	let sharedMemory;
	try { sharedMemory = new WebAssembly.Memory({ initial: 512, maximum: 4096, shared: true }); }
	catch (e) { /* not cross-origin isolated; non-shared modules still work */ }
	ctx.sharedMemory = sharedMemory;

	const importObject = {
		// Proxy stubs any WASI call we don't implement (sched_yield, ... pulled in by the
		// threaded libc) with a no-op returning 0, so instantiation never fails. args_get and the
		// fd_/path_ filesystem calls are real: they carry -play/-record and any fileRead/fileWrite
		// (see initWasm and the in-memory FS state at the top of this file).
		wasi_snapshot_preview1: new Proxy({
			args_sizes_get: (argcPtr, bufSizePtr) => {
				const enc = new TextEncoder();
				let bufSize = 0;
				for (const a of wasmArgs) bufSize += enc.encode(a).length + 1;
				const view = new DataView(ctx.memory.buffer);
				view.setUint32(argcPtr, wasmArgs.length, true);
				view.setUint32(bufSizePtr, bufSize, true);
				return 0;
			},
			args_get: (argvPtr, argvBufPtr) => {
				const enc = new TextEncoder();
				const view = new DataView(ctx.memory.buffer);
				let p = argvBufPtr;
				for (let i = 0; i < wasmArgs.length; i++) {
					view.setUint32(argvPtr + i * 4, p, true);
					const bytes = enc.encode(wasmArgs[i]);
					new Uint8Array(ctx.memory.buffer, p, bytes.length).set(bytes);
					view.setUint8(p + bytes.length, 0);
					p += bytes.length + 1;
				}
				return 0;
			},
			// fd 3 is the "." preopen the D side scans for (bops.wasm.file.findPreopen); paths
			// resolve directly against it into fsReadFiles (reads) / a collected blob (writes).
			fd_prestat_get: (fd, ptr) => {
				if (fd !== 3) return 8; // EBADF: only one preopen
				const view = new DataView(ctx.memory.buffer);
				view.setUint8(ptr, 0);            // tag: directory
				view.setUint32(ptr + 4, 1, true); // name length: "."
				return 0;
			},
			fd_prestat_dir_name: (fd, ptr, len) => {
				if (fd !== 3) return 8;
				new Uint8Array(ctx.memory.buffer, ptr, len).set(new TextEncoder().encode('.').subarray(0, len));
				return 0;
			},
			path_open: (dirfd, dirflags, pathPtr, pathLen, oflags, rightsBase, rightsInh, fdflags, openedFdPtr) => {
				const name = toJsString(pathPtr, pathLen, ctx.memory);
				const fd = fsNextFd++;
				if ((oflags & 0x1) || (oflags & 0x8)) { // O_CREAT | O_TRUNC -> writing
					fsOpenFds[fd] = { name, write: true, chunks: [] };
				} else {
					const data = fsReadFiles[name];
					if (!data) return 44; // ENOENT
					fsOpenFds[fd] = { name, data, offset: 0 };
				}
				new DataView(ctx.memory.buffer).setUint32(openedFdPtr, fd, true);
				return 0;
			},
			path_filestat_get: (dirfd, flags, pathPtr, pathLen, statPtr) => {
				const data = fsReadFiles[toJsString(pathPtr, pathLen, ctx.memory)];
				if (!data) return 44;
				new DataView(ctx.memory.buffer).setUint32(statPtr + 32, data.length, true); // filestat_t.size
				return 0;
			},
			fd_filestat_get: (fd, statPtr) => {
				const f = fsOpenFds[fd];
				if (!f) return 8;
				new DataView(ctx.memory.buffer).setUint32(statPtr + 32, f.data ? f.data.length : 0, true);
				return 0;
			},
			fd_read: (fd, iovsPtr, iovsLen, nreadPtr) => {
				const f = fsOpenFds[fd];
				if (!f || f.write) return 8;
				const view = new DataView(ctx.memory.buffer);
				let total = 0;
				for (let i = 0; i < iovsLen; i++) {
					const bufPtr = view.getUint32(iovsPtr + i * 8, true);
					const bufLen = view.getUint32(iovsPtr + i * 8 + 4, true);
					const n = Math.min(bufLen, f.data.length - f.offset);
					if (n <= 0) break;
					new Uint8Array(ctx.memory.buffer, bufPtr, n).set(f.data.subarray(f.offset, f.offset + n));
					f.offset += n;
					total += n;
				}
				view.setUint32(nreadPtr, total, true);
				return 0;
			},
			fd_write: (fd, iovs_ptr, iovs_len, nwritten_ptr) => {
				const view = new DataView(ctx.memory.buffer);
				const f = fsOpenFds[fd];
				if (f && f.write) {
					let written = 0;
					for (let i = 0; i < iovs_len; i++) {
						const ptr = view.getUint32(iovs_ptr + i * 8, true);
						const len = view.getUint32(iovs_ptr + i * 8 + 4, true);
						f.chunks.push(new Uint8Array(new Uint8Array(ctx.memory.buffer, ptr, len)));
						written += len;
					}
					view.setUint32(nwritten_ptr, written, true);
					return 0;
				}
				// fd 1/2: stdout/stderr -> console
				let text = '';
				let written = 0;
				for (let i = 0; i < iovs_len; i++) {
					const ptr = view.getUint32(iovs_ptr + i * 8, true);
					const len = view.getUint32(iovs_ptr + i * 8 + 4, true);
					text += toJsString(ptr, len, ctx.memory);
					written += len;
				}
				view.setUint32(nwritten_ptr, written, true);
				(fd === 2 ? console.error : console.log)(text.replace(/\n$/, ''));
				return 0;
			},
			// Patches bytes already written (a header field finalized later), in place in the
			// chunk they landed in, so it stays cheap on a file that is still being appended to.
			fd_pwrite: (fd, iovs_ptr, iovs_len, offset, nwritten_ptr) => {
				const view = new DataView(ctx.memory.buffer);
				const f = fsOpenFds[fd];
				if (!f || !f.write) return 8; // EBADF
				let pos = Number(offset);
				let written = 0;
				for (let i = 0; i < iovs_len; i++) {
					const ptr = view.getUint32(iovs_ptr + i * 8, true);
					const len = view.getUint32(iovs_ptr + i * 8 + 4, true);
					const src = new Uint8Array(ctx.memory.buffer, ptr, len);
					let done = 0;
					let start = 0;
					for (const c of f.chunks) {
						if (pos < start + c.length) {
							const n = Math.min(c.length - (pos - start), src.length - done);
							c.set(src.subarray(done, done + n), pos - start);
							done += n;
							pos += n;
							if (done === src.length) break;
						}
						start += c.length;
					}
					written += done;
				}
				view.setUint32(nwritten_ptr, written, true);
				return 0;
			},
			fd_close: (fd) => {
				const f = fsOpenFds[fd];
				if (f && f.write) {
					let total = 0;
					for (const c of f.chunks) total += c.length;
					const blob = new Uint8Array(total);
					let o = 0;
					for (const c of f.chunks) { blob.set(c, o); o += c.length; }
					downloadFile(f.name, blob);
				}
				delete fsOpenFds[fd];
				return 0;
			},
			proc_exit: (code) => { throw new Error('exit ' + code); },
			fd_seek: () => 0,
			clock_time_get: (_clock_id, _precision, time_ptr) => {
				const nowNs = performance.now() * 1_000_000;
				const view = new DataView(ctx.memory.buffer);
				view.setUint32(time_ptr,     nowNs >>> 0,                      true);
				view.setUint32(time_ptr + 4, Math.floor(nowNs / 0x100000000), true);
				return 0;
			},
		}, { get: (t, p) => (p in t ? t[p] : (() => 0)) }),
		env: { ...imports, ...(sharedMemory ? { memory: sharedMemory } : {}),
			jsDomSetInnerHtml: (idLen, idPtr, len, ptr) => { document.getElementById(toJsString(idPtr, idLen, ctx.memory)).innerHTML = toJsString(ptr, len, ctx.memory); },
			jsDomSetValue: (idLen, idPtr, len, ptr) => { document.getElementById(toJsString(idPtr, idLen, ctx.memory)).value = toJsString(ptr, len, ctx.memory); },
			jsDomGetValue: (idLen, idPtr, len, ptr) => { wasmStoreJsString(document.getElementById(toJsString(idPtr, idLen, ctx.memory)).value, ptr, len, ctx.memory); },
		}
	};

	return importObject;
}

function adoptInstance(module, instance, ctx) {
	ctx.wasm = instance;
	ctx.wasmModule = module;
	// Shared build imports memory (so exports.memory is absent); others export their own.
	ctx.memory = instance.exports.memory || ctx.sharedMemory;
	return instance;
}

// MUST stay async: Chrome throws on a synchronous `new WebAssembly.Instance` for a module over
// 8MB (a separate limit from the 4KB sync-compile one). Game modules are over it, the debugger's
// own module is not - so making this synchronous breaks every ilnm/multiinstance e2e test while
// test/e2e/debugger.spec.js still passes.
function instantiateModuleAsync(module, imports, ctx) {
	return WebAssembly.instantiate(module, buildImportObject(imports, ctx))
		.then(instance => adoptInstance(module, instance, ctx));
}

///////////////////////////////////////////////////////////////////////////////
// Gamepad

// var gamepad;
// window.addEventListener("gamepadconnected", (evt) => {gamepad = evt.gamepad;});
// window.addEventListener("gamepaddisconnected", (evt) => {gamepad = null;});

// Phone IMU, passed through exactly as DeviceMotionEvent reports it: no projection, scaling or unit
// conversion. bops.devicemotion turns it into camera axes, using gravity to work out which way the
// phone is held - which a projection here could only guess at.
const deviceMotionRaw = new Float32Array(12);

// screen.orientation.angle is the angle of the *screen*, which an orientation lock (fullscreen takes
// one on some Android browsers) can pin to a value the phone is no longer held at. The viewport
// aspect is the ground truth for which way round the phone is, so a disagreement overrides it.
function screenAngle() {
	const reported = screen.orientation ? screen.orientation.angle : (window.orientation || 0);
	const landscape = window.innerWidth > window.innerHeight;
	if (landscape === (reported === 90 || reported === 270))
		return reported;
	return landscape ? 90 : 0;
}

function listenDeviceMotion() {
	window.addEventListener('devicemotion', (evt) => {
		const xyz = (v, base) => {
			deviceMotionRaw[base + 0] = (v && v.x) || 0;
			deviceMotionRaw[base + 1] = (v && v.y) || 0;
			deviceMotionRaw[base + 2] = (v && v.z) || 0;
		};
		xyz(evt.acceleration, 0);
		xyz(evt.accelerationIncludingGravity, 3);
		const rot = evt.rotationRate;
		deviceMotionRaw[6] = (rot && rot.alpha) || 0;
		deviceMotionRaw[7] = (rot && rot.beta) || 0;
		deviceMotionRaw[8] = (rot && rot.gamma) || 0;
		deviceMotionRaw[9] = evt.interval || 0;
		deviceMotionRaw[10] = screenAngle();
		deviceMotionRaw[11] += 1;
	});
}

function requestMotionPermission() {
	// iOS only: gated behind a permission request that must run inside a user gesture.
	if (typeof DeviceMotionEvent === 'undefined' || typeof DeviceMotionEvent.requestPermission !== 'function')
		return;
	DeviceMotionEvent.requestPermission().catch(err => console.warn('Motion permission denied:', err));
}

///////////////////////////////////////////////////////////////////////////////
// Mobile session: fullscreen to get rid of the URL bar, and a wake lock so the
// screen does not blank while playing with the gyro (no touches for a while).

let wakeLock = null;

async function acquireWakeLock() {
	if (!navigator.wakeLock || document.visibilityState !== 'visible')
		return;
	try {
		wakeLock = await navigator.wakeLock.request('screen');
		wakeLock.addEventListener('release', () => { wakeLock = null; });
	} catch (err) {
		console.warn('Wake lock failed:', err);
	}
}

function setupMobileSession() {
	// The screen wake lock is dropped whenever the tab is hidden, so re-take it on return.
	document.addEventListener('visibilitychange', () => { if (!wakeLock) acquireWakeLock(); });
	acquireWakeLock();

	// Fullscreen and the iOS sensor permission both require a user gesture. Touch only:
	// on desktop a stray click yanking the browser into fullscreen is obnoxious. The listener
	// stays attached because rotating the phone can drop fullscreen and bring the URL bar back
	// over the canvas; the next touch then takes it again. Permission is asked for once.
	let askedMotion = false;
	const onGesture = (evt) => {
		if (!askedMotion) {
			askedMotion = true;
			requestMotionPermission();
		}
		if (evt.pointerType === 'touch' && document.documentElement.requestFullscreen && !document.fullscreenElement)
			document.documentElement.requestFullscreen().catch(err => console.warn('Fullscreen failed:', err));
	};
	window.addEventListener('pointerdown', onGesture);
}

function makeGamepadExports(ctx) {
	return {
	jsGetGamepadState: (id, ptr) => {
		const view = new DataView(ctx.memory.buffer);

		const override = ctx.padOverride && ctx.padOverride[id];
		if (override) {
			new Uint8Array(ctx.memory.buffer, ptr, override.length).set(override);
			return;
		}

		if (id === 0) {
			for (let i = 0; i < 12; i++)
				view.setFloat32(ptr + 60 + i * 4, deviceMotionRaw[i], true);
		}

		const gamepad = navigator.getGamepads()[id];
		if (!gamepad)
			return;

		let offset = ptr;

		for (let i = 0; i < 4; i++) {
			view.setFloat32(offset, gamepad.axes[i], true);
			offset += 4;
		}

		for (let i = 0; i < 17; i++) {
			view.setUint8(offset, gamepad.buttons[i].pressed ? 1 : 0);
			offset += 1;
		}
	},
	jsSetRumble: (id, slow, fast) => {
		const gamepads = navigator.getGamepads();
		const gamepad = gamepads[id];

		// Note: rumble is not supported in Firefox
		if (gamepad && gamepad.vibrationActuator) {
			gamepad.vibrationActuator.playEffect("dual-rumble", {
				startDelay: 0,
				duration: 100, // in milliseconds
				weakMagnitude: slow, // 0.0 to 1.0
				strongMagnitude: fast // 0.0 to 1.0
			}).catch(err => console.warn("Rumble failed:", err));
		}
		gamepad.vibrationActuator.playEffect();
	}
	};
}

///////////////////////////////////////////////////////////////////////////////
// Save data

function makeSaveDataExports(ctx) {
	return {
	jsLocalStoreSet: (keyLen, keyPtr, dataLen, dataPtr) => {
		localStorage.setItem(toJsString(keyPtr, keyLen, ctx.memory), toJsString(dataPtr, dataLen, ctx.memory));
	},
	jsLocalStoreGet: (keyLen, keyPtr, dataLen, dataPtr) => {
		const str = localStorage.getItem(toJsString(keyPtr, keyLen, ctx.memory));
		if (str === null)
			return 0;
		return wasmStoreJsString(str, dataPtr, dataLen, ctx.memory);
	},
	};
}

///////////////////////////////////////////////////////////////////////////////
// AudioWorklet engine (low-latency streaming)
//
// The worklet runs a SECOND wasm instance over the same shared memory and calls
// audioRender/audioCapture on the audio thread. wasm has no thread runtime, so we
// hand it a dedicated stack + TLS block (carved out by the main-thread instance)
// and bring the thread up by hand before invoking any export.

// One AudioContext for the page, but a worklet node per wasm instance (ctx.audioNode): the
// debugger hosts a game module that renders its own audio over its own memory.
let audioContext;


// An AudioContext constructed before the page has ever been interacted with starts suspended, and
// on mobile resume() on such a context is unreliable: it resolves while the context stays silent.
// Constructing it from within a gesture instead gives a context that is running from the start.
const activationEvents = ['mousedown', 'keydown', 'pointerup', 'touchend'];

function onFirstGesture(fn) {
	const run = () => {
		for (const name of activationEvents)
			window.removeEventListener(name, run);
		fn();
	};
	for (const name of activationEvents)
		window.addEventListener(name, run);
}

// The context can also be suspended again later: the tab going hidden, a phone call, a headset
// unplugged. These listeners stay attached for the session and nurse it back on any interaction.
function keepAudioRunning() {
	const resume = () => {
		if (audioContext && audioContext.state === 'suspended')
			audioContext.resume().catch((e) => console.warn('audio resume failed', e));
	};
	// suspend audio when screen is off or another tab/app is up
	const onVisibility = () => {
		if (!audioContext)
			return;
		if (document.visibilityState === 'hidden')
			audioContext.suspend().catch((e) => console.warn('audio suspend failed', e));
		else
			resume();
	};
	for (const name of activationEvents)
		window.addEventListener(name, resume);
	document.addEventListener('visibilitychange', onVisibility);
	resume();
}

// How far ahead of the playhead the fallback keeps the node's ring. The worklet path has no such
// number: there the render happens on the audio thread, at its own quantum.
const fallbackLatency = 0.1;

async function setupAudioEngine(ctx, sampleRate) {
	// The worklet re-instantiates the wasm over the same memory, which only works if memory is
	// shared. Where it is not, the same render runs on the main thread into a ring the node drains.
	// ?audio=main forces the fallback on a page that could run the worklet path, so the main-thread
	// render is reachable for testing on any build.
	const forced = new URLSearchParams(location.search).get('audio') === 'main';
	const shared = !forced && ctx.memory.buffer instanceof SharedArrayBuffer && !!ctx.wasm.exports.audioThreadStackTop;
	if (!shared)
		console.warn('Rendering audio on the main thread: wasm memory is not shared (needs a --shared-memory build served cross-origin isolated).');
	if (!audioContext) audioContext = new AudioContext({ sampleRate });
	if (audioContext.state === 'suspended')
		audioContext.resume().catch((e) => console.warn('audio resume failed', e));
	if (audioContext.sampleRate !== sampleRate)
		console.warn('AudioContext sampleRate ' + audioContext.sampleRate + ' != requested ' + sampleRate);

	await audioContext.audioWorklet.addModule('audio-engine.js');

	const audioEngineNode = new AudioWorkletNode(audioContext, 'audio-engine', {
		numberOfInputs: 1,
		numberOfOutputs: 1,
		outputChannelCount: [2],
		processorOptions: shared ? {
			module: ctx.wasmModule,
			memory: ctx.memory,
			stackTop: ctx.wasm.exports.audioThreadStackTop(),
			tlsBase: ctx.wasm.exports.audioThreadTlsBase(),
		} : { fallback: true },
	});
	// On the fallback path the node reports how much it still holds, which is the only feedback in
	// the system and stays inside the audio side: the game never sees it.
	audioEngineNode.port.onmessage = (e) => {
		if (typeof e.data === 'number')
			ctx.audioFill = e.data;
		else
			console.error(e.data);
	};
	audioEngineNode.connect(audioContext.destination);
	ctx.audioNode = audioEngineNode;
	ctx.audioFallback = !shared;
	ctx.audioFill = 0;
	ctx.audioTarget = Math.round(audioContext.sampleRate * fallbackLatency);
	keepAudioRunning();
}

function makeSoundEngineExports(ctx) {
	return {
	jsSoundOutputInit: (sampleRate) => {
		const start = () => setupAudioEngine(ctx, sampleRate).catch((e) => console.error('audio engine init failed', e));
		if (navigator.userActivation && !navigator.userActivation.hasBeenActive)
			onFirstGesture(start);
		else
			start();
	},
	jsAudioWanted: () => {
		if (!ctx.audioFallback || !ctx.audioNode)
			return 0;
		const want = ctx.audioTarget - ctx.audioFill;
		return want > 0 ? want : 0;
	},
	jsAudioPush: (ptr, frames) => {
		if (!ctx.audioNode || frames <= 0)
			return;
		// A copy, not a view: the node lives on another thread and this memory is not shared.
		const chunk = new Float32Array(new Float32Array(ctx.memory.buffer, ptr, frames * 2));
		ctx.audioFill += frames;
		ctx.audioNode.port.postMessage(chunk, [chunk.buffer]);
	},
	jsSoundInputInit: () => {
		if (ctx.audioFallback) { console.warn('Microphone input needs the worklet path (cross-origin isolated).'); return; }
		if (!navigator.mediaDevices) { console.warn('getUserMedia unavailable'); return; }
		// Disable the browser's voice-processing DSP: echo cancellation in particular
		// adds hundreds of ms of buffering. We want the raw low-latency signal.
		const constraints = { audio: {
			echoCancellation: false,
			noiseSuppression: false,
			autoGainControl: false,
			latency: 0,
		} };
		navigator.mediaDevices.getUserMedia(constraints).then((stream) => {
			const src = audioContext.createMediaStreamSource(stream);
			const connect = () => { ctx.audioNode ? src.connect(ctx.audioNode) : setTimeout(connect, 50); };
			connect();
		}).catch((e) => console.warn('microphone access denied', e));
	},
	};
}

///////////////////////////////////////////////////////////////////////////////
// MIDI (Web MIDI API, main thread)

let midiAccess;

function deliverMidi(ctx, data) {
	const ptr = ctx.wasm.exports.midiInBuffer();
	const n = Math.min(data.length, 64);
	new Uint8Array(ctx.memory.buffer, ptr, n).set(data.subarray(0, n));
	ctx.wasm.exports.hookMidi(ptr, n);
}

function makeMidiExports(ctx) {
	return {
	jsMidiInit: () => {
		if (!navigator.requestMIDIAccess) { console.warn('Web MIDI not supported'); return; }
		navigator.requestMIDIAccess().then((access) => {
			midiAccess = access;
			const bind = (input) => { input.onmidimessage = (msg) => deliverMidi(ctx, msg.data); };
			midiAccess.inputs.forEach(bind);
			midiAccess.onstatechange = (e) => {
				if (e.port.type === 'input' && e.port.state === 'connected') bind(e.port);
			};
		}).catch((e) => console.warn('MIDI access denied', e));
	},
	jsSendMidi: (bufferLen, bufferPtr) => {
		if (!midiAccess) return false;
		const data = new Uint8Array(new Uint8Array(ctx.memory.buffer, bufferPtr, bufferLen));
		midiAccess.outputs.forEach((o) => o.send(data));
		return true;
	},
	};
}

///////////////////////////////////////////////////////////////////////////////
// WebGL

// Notable differences with OpenGL: objects and uniform locations are JS objects in WebGL,
// so to keep the illusion that they are integers in OpenGL, a hashmap is used.

var gl;
var glCanvas;     // canvas element, kept for pointer-lock based mouse capture
var windowClosed = false;

function compileShaderProgram(gs, vsSource, fsSource, gmSource)
{
	webglHeader = '#version 300 es\nprecision highp float;\nprecision highp int;';
	vsSource = vsSource.replace(/^#version\s+330/, webglHeader);
	fsSource = fsSource.replace(/^#version\s+330/, webglHeader);

	var vertShader = gl.createShader(gl.VERTEX_SHADER);
	gl.shaderSource(vertShader, vsSource);
	gl.compileShader(vertShader);

	if (!gl.getShaderParameter(vertShader, gl.COMPILE_STATUS)) {
		console.error("Vertex shader:", gl.getShaderInfoLog(vertShader));
		console.error("Source:", vsSource);
		return 0;
	}

	var fragShader = gl.createShader(gl.FRAGMENT_SHADER);
	gl.shaderSource(fragShader, fsSource);
	gl.compileShader(fragShader);

	if (!gl.getShaderParameter(fragShader, gl.COMPILE_STATUS)) {
		console.error("Fragment shader:", gl.getShaderInfoLog(fragShader));
		console.error("Source:", fsSource);
		return 0;
	}

	var program = gl.createProgram();
	gl.attachShader(program, vertShader);
	gl.attachShader(program, fragShader);
	gl.linkProgram(program);

	if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
		console.error(gl.getProgramInfoLog(program));
		return 0;
	}

	const id = gs.nextProgramId++;
	gs.programMap[id] = program;
	return id;
}

function fromWasmStringz(ptr, memObj)
{
	const mem = new Uint8Array(memObj.buffer);
	let end = ptr;
	while (mem[end] !== 0) end++;
	// .slice copies out: TextDecoder rejects SharedArrayBuffer-backed views.
	const strBytes = mem.slice(ptr, end);
	return new TextDecoder('utf-8').decode(strBytes);
}

function ptrFloat(ptr, count, mem) { return new Float32Array(mem.buffer, ptr, count); }

// One instance's WebGL object tables: wasm-side integer ids -> live WebGL objects, minted
// from per-table counters. The ids are per-instance, the WebGL context (gl) is shared - so
// hosting a second wasm module (e.g. a game inside the debugger) gives it its own makeGlState()
// and their id spaces can't collide even though both draw into the one context.
function makeGlState() {
	return {
		bufferMap: {},
		vaoMap: {},
		programMap: {},
		textureMap: {},
		uniformLocationMap: {}, // id -> WebGLUniformLocation
		uniformLookupMap: {},   // "programId:name" -> id
		fbMap: {},
		rbMap: {},
		nextBufferId: 1,
		nextVaoId: 1,
		nextProgramId: 1,
		nextTextureId: 1,
		nextUniformLocationId: 1,
		nextFbId: 1,
		nextRbId: 1,
	};
}

function typeSizeGl(type) {
	switch (type) {
		case gl.FLOAT: return 4;
		case gl.INT: return 4;
		case gl.UNSIGNED_INT: return 4;
		case gl.BYTE: return 1;
		case gl.UNSIGNED_BYTE: return 1;
		case gl.SHORT: return 2;
		case gl.UNSIGNED_SHORT: return 2;
		case gl.DOUBLE: return 8;
		default: throw new Error("Unknown type " + type);
	}
}

function typeSizeGl(type) {
	const GL_TYPE_SIZE = {
		[gl.BYTE]: 1, [gl.UNSIGNED_BYTE]: 1, [gl.SHORT]: 2, [gl.UNSIGNED_SHORT]: 2,
		[gl.INT]: 4, [gl.UNSIGNED_INT]: 4, [gl.FLOAT]: 4, [gl.DOUBLE]: 8
	};
	const size = GL_TYPE_SIZE[type];
	if (size === undefined) {
		throw new Error("Unknown type " + type);
	}
	return size;
}

function formatChannelsGl(format)
{
	switch (format)
	{
		case gl.RGBA: return 4;
		case gl.RGB: return 3;
		case gl.RG: return 2;
		case gl.RED: return 1;
		case gl.LUMINANCE: return 1;
		case gl.LUMINANCE_ALPHA: return 2;
		case gl.DEPTH_COMPONENT: return 1;
		case gl.DEPTH_STENCIL: return 1;
		default: throw new Error("Unknown format " + format);
	}
}

function makeOpenglExports(ctx) {
	const gs = ctx.glState;
	const { bufferMap, vaoMap, programMap, textureMap, uniformLocationMap, uniformLookupMap, fbMap, rbMap } = gs;
	// A hosted instance places its own default-framebuffer rects: the host hands it a placement
	// through the debugPlace export and the guest's executor maps its viewport/scissor itself,
	// so the GL entry points here are plain passthroughs.
	return {
	glGetUniformLocation: (program, namePtr) => {
		const name = fromWasmStringz(namePtr, ctx.memory);
		const key = program + ":" + name;

		if (uniformLookupMap[key] !== undefined)
			return uniformLookupMap[key];

		const loc = gl.getUniformLocation(programMap[program], name);
		if (loc === null)
			return 0;

		const id = gs.nextUniformLocationId++;
		uniformLocationMap[id] = loc;
		uniformLookupMap[key] = id;
		return id;
	},
	js_compileShaderProgram: (vertLength, vertPtr, fragLength, fragPtr, geomLength, geomPtr) => compileShaderProgram(gs, toJsString(vertPtr, vertLength, ctx.memory), toJsString(fragPtr, fragLength, ctx.memory), toJsString(geomPtr, geomLength, ctx.memory)),
	glActiveTexture: (texture) => { gl.activeTexture(texture); },
	glBindBuffer: (target, id) => { gl.bindBuffer(target, bufferMap[id]); },
	glBindBufferBase: (target, index, id) => { gl.bindBufferBase(target, index, bufferMap[id]); },
	glBindBufferRange: (target, index, id, offset, size) => { gl.bindBufferRange(target, index, bufferMap[id], offset, size); },
	glBindFramebuffer: (target, framebufferId) => { gl.bindFramebuffer(target, fbMap[framebufferId] || null); },
	glBindRenderbuffer: (target, id) => { gl.bindRenderbuffer(target, rbMap[id] || null); },
	glBindTexture: (target, texture) => { gl.bindTexture(target, textureMap[texture]); },
	glBindVertexArray: (id) => { gl.bindVertexArray(vaoMap[id]); },
	glBlendFunc: (i, s, d) => { gl.blendFunc(i, s, d); },
	glBufferData: (target, size, dataPtr, usage) => {gl.bufferData(target, (dataPtr === 0) ? size : new Uint8Array(ctx.memory.buffer, dataPtr, size), usage);},
	glBufferSubData: (target, offset, size, dataPtr) => {gl.bufferSubData(target, offset, new Uint8Array(ctx.memory.buffer, dataPtr, size));},
	glCheckFramebufferStatus: (target) => { return gl.checkFramebufferStatus(target); },
	glClear: (mask) => { gl.clear(mask); },
	glClearColor: (r, g, b, a) => { gl.clearColor(r, g, b, a); },
	glCreateBuffer: () => { const id = gs.nextBufferId++; bufferMap[id] = gl.createBuffer(); return id; },
	glCreateFrameBuffer: () => { const id = gs.nextFbId++; fbMap[id] = gl.createFramebuffer(); return id; },
	glCreateRenderBuffer: () => { const id = gs.nextRbId++; rbMap[id] = gl.createRenderbuffer(); return id; },
	glCreateTexture: () => { const id = gs.nextTextureId++; textureMap[id] = gl.createTexture(); return id; },
	glCreateVertexArray: () => { const id = gs.nextVaoId++; vaoMap[id] = gl.createVertexArray(); return id; },
	glCullFace: (mode) => { gl.cullFace(mode); },
	glDeleteBuffer: (id) => { gl.deleteBuffer(bufferMap[id]); },
	glDeleteFramebuffer: (id) => { gl.deleteFramebuffer(fbMap[id]); },
	glDeleteProgram: (id) => { gl.deleteProgram(programMap[id]); },
	glDeleteRenderbuffer: (id) => { gl.deleteRenderbuffer(rbMap[id]); },
	glDeleteTexture: (id) => { gl.deleteTexture(textureMap[id]); },
	glDeleteVertexArray: (id) => { gl.deleteVertexArray(vaoMap[id]); },
	glDisable: (cap) => { gl.disable(cap); },
	glDisableVertexAttribArray: (index) => { gl.disableVertexAttribArray(index); },
	glDrawArraysInstanced: (primitive, offset, verts, instances) => { return gl.drawArraysInstanced(primitive, offset, verts, instances) },
	glDrawElements: (mode, count, type, offset) => { gl.drawElements(mode, count, type, offset); },
	glDrawElementsInstanced: (mode, count, type, offset, instances) => { gl.drawElementsInstanced(mode, count, type, offset, instances); },
	glEnable: (cap) => { gl.enable(cap); },
	glEnableVertexAttribArray: (index) => { gl.enableVertexAttribArray(index); },
	glFramebufferRenderbuffer: (tgt, att, rbTgt, id) => { gl.framebufferRenderbuffer(tgt, att, rbTgt, rbMap[id]); },
	glFramebufferTexture2D: (target, attachment, textarget, texture, level) => { gl.framebufferTexture2D(target, attachment, textarget, textureMap[texture], level); },
	glGetAttribLocation: (program, namePtr) => { return gl.getAttribLocation(programMap[program], fromWasmStringz(namePtr, ctx.memory)); },
	glGetUniformBlockIndex: (program, namePtr) => { return gl.getUniformBlockIndex(programMap[program], fromWasmStringz(namePtr, ctx.memory)); },
	glReadPixels: (x, y, w, h, format, type, ptr) => { const pixels = new Uint8Array(ctx.memory.buffer, ptr, w * h * 4); gl.readPixels(x, y, w, h, format, type, pixels); }, // TODO: hardcoded 4 channels
	glRenderbufferStorage: (target, internalformat, w, h) => { gl.renderbufferStorage(target, internalformat, w, h); },
	glScissor: (x, y, w, h) => { gl.scissor(x, y, Math.max(0, w), Math.max(0, h)); },
	glTexImage2D: (target, level, internalFormat, width, height, border, format, type, data) => {gl.texImage2D(target, level, internalFormat, width, height, border, format, type, (data == null) ? data : new Uint8Array(ctx.memory.buffer, data, width * height * typeSizeGl(type) * formatChannelsGl(format)));},
	glTexParameteri: (target, pname, value) => { gl.texParameteri(target, pname, value); },
	glTexStorage2D: (target, levels, internalformat,width, height) => { return gl.texStorage2D(target, levels, internalformat,width, height); },
	glTexSubImage2D: (target, level, xoffset, yoffset, width, height, format, type, ptr) => {gl.texSubImage2D(target, level, xoffset, yoffset, width, height, format, type, new Uint8Array(ctx.memory.buffer, ptr, width * height * typeSizeGl(type) * formatChannelsGl(format)));},
	glCopyTexSubImage2D: (target, level, xoffset, yoffset, x, y, width, height) => { gl.copyTexSubImage2D(target, level, xoffset, yoffset, x, y, width, height); },
	glBlitFramebuffer: (srcX0, srcY0, srcX1, srcY1, dstX0, dstY0, dstX1, dstY1, mask, filter) => { gl.blitFramebuffer(srcX0, srcY0, srcX1, srcY1, dstX0, dstY0, dstX1, dstY1, mask, filter); },
	glPixelStorei: (pname, param) => { gl.pixelStorei(pname, param); },
	glUniform1f: (location, v0) => { gl.uniform1f(uniformLocationMap[location], v0); },
	glUniform1i: (location, v0) => { gl.uniform1i(uniformLocationMap[location], v0); },
	glUniform2f: (location, v0, v1) => { gl.uniform2f(uniformLocationMap[location], v0, v1); },
	glUniform2i: (location, v0, v1) => { gl.uniform2i(uniformLocationMap[location], v0, v1); },
	glUniform3f: (location, v0, v1, v2) => { gl.uniform3f(uniformLocationMap[location], v0, v1, v2); },
	glUniform3i: (location, v0, v1, v2) => { gl.uniform3i(uniformLocationMap[location], v0, v1, v2); },
	glUniform4f: (location, v0, v1, v2, v3) => { gl.uniform4f(uniformLocationMap[location], v0, v1, v2, v3); },
	glUniform4i: (location, v0, v1, v2, v3) => { gl.uniform4i(uniformLocationMap[location], v0, v1, v2, v3); },
	glUniformBlockBinding: (program, uniformBlockIndex, uniformBlockBinding) => { gl.uniformBlockBinding(programMap[program], uniformBlockIndex, uniformBlockBinding); },
	glUniformMatrix2fv: (location, count, transpose, valuePtr) => { gl.uniformMatrix2fv(uniformLocationMap[location], !!transpose, ptrFloat(valuePtr, 4, ctx.memory)); },
	glUniformMatrix3fv: (location, count, transpose, valuePtr) => { gl.uniformMatrix3fv(uniformLocationMap[location], !!transpose, ptrFloat(valuePtr, 9, ctx.memory)); },
	glUniformMatrix4fv: (location, count, transpose, valuePtr) => { gl.uniformMatrix4fv(uniformLocationMap[location], !!transpose, ptrFloat(valuePtr, 16, ctx.memory)); },
	glUseProgram: (program) => { gl.useProgram(programMap[program]); },
	glVertexAttribDivisor: (index, div) => { gl.vertexAttribDivisor(index, div); },
	glVertexAttribIPointer: (index, size, type, stride, pointer) => { gl.vertexAttribIPointer(index, size, type, stride, pointer); },
	glVertexAttribPointer: (index, size, type, normalized, stride, pointer) => { gl.vertexAttribPointer(index, size, type, normalized, stride, pointer); },
	glViewport: (x, y, w, h) => { gl.viewport(x, y, Math.max(0, w), Math.max(0, h)); },
	};
}

///////////////////////////////////////////////////////////////////////////////
// WebGPU
//
// The browser twin of the native wgpu executor (source/wip/wgpuexec.d). The wasm records a
// frame as render passes + draw commands (bops.gfx.cmd) and replays it here through the jsGpu*
// entry points, so the D side names no graphics API and holds no GPU object: pipelines, bind
// groups and buffers all live in this file, keyed by the ids the recording carries.
//
// Enabled with ?gpu=webgpu. Without it, or when no device is granted, jsGpuActive reports 0 and
// everything stays on WebGL2.

let gpuDevice;
let gpuFormat;
let gpuContext;     // the canvas' WebGPU context, configured by jsInitWindow
let gpuCanvasDepth; // { texture, view, width, height }: depth attachment for the canvas
let gpuStatic;      // shader module, layouts, samplers, pipeline cache: shared by every instance
let gpuFrame;       // { encoder, pass, canvasView, flip, depthCleared } while encoding a frame
const gpuWarned = {};

function gpuWarnOnce(key, message) {
	if (gpuWarned[key])
		return;
	gpuWarned[key] = true;
	console.warn('webgpu: ' + message);
}

async function requestGpuDevice() {
	if (!navigator.gpu) {
		console.error('WebGPU is not available in this browser; staying on WebGL2');
		return;
	}
	const adapter = await navigator.gpu.requestAdapter();
	if (!adapter) {
		console.error('No WebGPU adapter; staying on WebGL2');
		return;
	}
	gpuDevice = await adapter.requestDevice();
	gpuDevice.addEventListener('uncapturederror', (e) => console.error('webgpu:', e.error.message));
	gpuFormat = navigator.gpu.getPreferredCanvasFormat();
}

// Per-instance id tables. The ids come from the wasm (a texture id is what a draw command names,
// a target id what a pass names), and a hosted second module has its own set - like makeGlState.
function makeGpuState() {
	return {
		textures: {},  // id -> { texture, view }
		targets: {},   // id -> { view, depthView, width, height }
		models: {},    // model address -> geometry buffers
		uniforms: {},  // model address -> { buffer, size, group }
		groups: {},    // "texture:sampler" -> GPUBindGroup
		nextId: 1,
	};
}

// One 4-byte uniform per y-orientation, selected per pass: -1 makes an offscreen pass render
// upside down, since WebGPU's framebuffer y runs opposite to GL's and the recorded UVs are GL's.
function gpuCreateStatic(wgsl) {
	const uniformLayout = gpuDevice.createBindGroupLayout({ entries: [{
		binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT,
		buffer: { type: 'uniform', hasDynamicOffset: true, minBindingSize: 256 },
	}]});
	const textureLayout = gpuDevice.createBindGroupLayout({ entries: [
		{ binding: 0, visibility: GPUShaderStage.FRAGMENT, texture: { sampleType: 'float' } },
		{ binding: 1, visibility: GPUShaderStage.FRAGMENT, sampler: { type: 'filtering' } },
	]});
	const passLayout = gpuDevice.createBindGroupLayout({ entries: [{
		binding: 0, visibility: GPUShaderStage.VERTEX,
		buffer: { type: 'uniform', minBindingSize: 4 },
	}]});

	const samplers = [];
	for (let i = 0; i < 4; i++) {
		const address = (i & 1) ? 'clamp-to-edge' : 'repeat';
		const filter = (i & 2) ? 'nearest' : 'linear';
		samplers.push(gpuDevice.createSampler({
			addressModeU: address, addressModeV: address, addressModeW: address,
			magFilter: filter, minFilter: filter, mipmapFilter: 'nearest',
		}));
	}

	const flipGroups = [1, -1].map((sign) => {
		const buffer = gpuDevice.createBuffer({ size: 4, usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST });
		gpuDevice.queue.writeBuffer(buffer, 0, new Float32Array([sign]));
		return gpuDevice.createBindGroup({ layout: passLayout, entries: [{ binding: 0, resource: { buffer } }] });
	});

	gpuStatic = {
		shader: gpuDevice.createShaderModule({ code: wgsl }),
		layout: gpuDevice.createPipelineLayout({ bindGroupLayouts: [uniformLayout, textureLayout, passLayout] }),
		uniformLayout, textureLayout, samplers, flipGroups,
		pipelines: {},
	};
}

// bops.gfx.cmd's BlendFactor order.
const GPU_BLEND = ['zero', 'one', 'src', 'one-minus-src', 'src-alpha', 'one-minus-src-alpha',
	'dst', 'one-minus-dst', 'dst-alpha', 'one-minus-dst-alpha'];
const GPU_CULL = ['none', 'front', 'back'];
const GPU_VERTEX_LAYOUT = [
	{ arrayStride: 12, attributes: [{ shaderLocation: 0, offset: 0, format: 'float32x3' }] },
	{ arrayStride: 16, attributes: [{ shaderLocation: 1, offset: 0, format: 'float32x4' }] },
	{ arrayStride: 8,  attributes: [{ shaderLocation: 2, offset: 0, format: 'float32x2' }] },
	{ arrayStride: 4,  attributes: [{ shaderLocation: 3, offset: 0, format: 'uint32' }] },
	{ arrayStride: 8,  attributes: [{ shaderLocation: 4, offset: 0, format: 'float32x2' }] },
];
const GPU_VERTEX_STRIDES = [12, 16, 8, 4, 8];

// The key is what bops.gfx.webgpuexec.pipelineKey packed: blend factors, depth test, cull mode
// and the y-flip that also selects the offscreen rgba8 format over the canvas one.
function gpuPipeline(key) {
	const hit = gpuStatic.pipelines[key];
	if (hit)
		return hit;
	const blend = { color: {
		operation: 'add', srcFactor: GPU_BLEND[key & 15], dstFactor: GPU_BLEND[(key >> 4) & 15],
	}};
	blend.alpha = blend.color;
	const depth = ((key >> 8) & 1) !== 0;
	const flip = ((key >> 11) & 1) !== 0;
	const pipeline = gpuDevice.createRenderPipeline({
		layout: gpuStatic.layout,
		vertex: { module: gpuStatic.shader, entryPoint: 'vs_main', buffers: GPU_VERTEX_LAYOUT },
		fragment: { module: gpuStatic.shader, entryPoint: 'fs_main', targets: [{
			format: flip ? 'rgba8unorm' : gpuFormat, blend, writeMask: GPUColorWrite.ALL,
		}]},
		primitive: {
			topology: 'triangle-list',
			frontFace: flip ? 'cw' : 'ccw',
			cullMode: GPU_CULL[(key >> 9) & 3],
		},
		depthStencil: {
			format: 'depth24plus',
			depthWriteEnabled: depth,
			depthCompare: depth ? 'less' : 'always',
		},
	});
	gpuStatic.pipelines[key] = pipeline;
	return pipeline;
}

// WebGPU has no 3-channel format, and a shared-memory view cannot be handed to writeTexture,
// so pixels are always copied out (and rgb padded to rgba) on the way to the GPU.
function gpuPixels(channels, width, height, ptr, mem) {
	const src = new Uint8Array(mem.buffer, ptr, width * height * channels);
	if (channels === 3) {
		const out = new Uint8Array(width * height * 4);
		for (let i = 0, o = 0; i < src.length; i += 3, o += 4) {
			out[o] = src[i];
			out[o + 1] = src[i + 1];
			out[o + 2] = src[i + 2];
			out[o + 3] = 255;
		}
		return { format: 'rgba8unorm', data: out, bytesPerRow: width * 4 };
	}
	const formats = { 1: 'r8unorm', 2: 'rg8unorm', 4: 'rgba8unorm' };
	if (!formats[channels])
		throw new Error('webgpu: unsupported channel count ' + channels);
	return { format: formats[channels], data: src.slice(), bytesPerRow: width * channels };
}

function gpuGrowBuffer(entry, field, needed, usage) {
	if (entry[field] && entry[field + 'Size'] >= needed)
		return entry[field];
	if (entry[field])
		entry[field].destroy();
	const size = Math.max(needed, 4096);
	entry[field] = gpuDevice.createBuffer({ size, usage: usage | GPUBufferUsage.COPY_DST });
	entry[field + 'Size'] = size;
	return entry[field];
}

function gpuEndPass() {
	if (gpuFrame && gpuFrame.pass) {
		gpuFrame.pass.end();
		gpuFrame.pass = null;
	}
}

function gpuCanvasDepthView(width, height) {
	if (gpuCanvasDepth && gpuCanvasDepth.width === width && gpuCanvasDepth.height === height)
		return gpuCanvasDepth.view;
	if (gpuCanvasDepth)
		gpuCanvasDepth.texture.destroy();
	const texture = gpuDevice.createTexture({
		size: [width, height, 1], format: 'depth24plus', usage: GPUTextureUsage.RENDER_ATTACHMENT,
	});
	gpuCanvasDepth = { texture, view: texture.createView(), width, height };
	return gpuCanvasDepth.view;
}

// GL measures viewport/scissor y from the bottom of the attachment. So does an offscreen pass
// here (it renders y-flipped, which puts GL's row 0 in WebGPU's row 0), but the canvas is
// top-down, so a target-0 rect is mirrored. Rects are clamped: WebGPU rejects one that pokes
// outside the attachment, where GL silently ignored the excess.
function gpuRect(x, y, w, h, width, height, flip) {
	const top = flip ? y : height - y - h;
	const x0 = Math.max(0, Math.min(x, width));
	const y0 = Math.max(0, Math.min(top, height));
	return [x0, y0, Math.max(0, Math.min(x + w, width) - x0), Math.max(0, Math.min(top + h, height) - y0)];
}

function makeGpuExports(ctx) {
	const gs = ctx.gpuState;
	const mem = () => ctx.memory;

	function textureGroup(texture, sampler) {
		const key = texture + ':' + sampler;
		const hit = gs.groups[key];
		if (hit)
			return hit;
		const entry = gs.textures[texture] || gs.textures[0];
		const group = gpuDevice.createBindGroup({ layout: gpuStatic.textureLayout, entries: [
			{ binding: 0, resource: entry.view },
			{ binding: 1, resource: gpuStatic.samplers[sampler] },
		]});
		gs.groups[key] = group;
		return group;
	}

	function createTexture(width, height, channels, ptr, usage) {
		const { format, data, bytesPerRow } = gpuPixels(channels, width, height, ptr, mem());
		const texture = gpuDevice.createTexture({
			size: [width, height, 1], format,
			usage: usage | GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST,
		});
		gpuDevice.queue.writeTexture({ texture }, data, { bytesPerRow, rowsPerImage: height },
			[width, height, 1]);
		const id = gs.nextId++;
		gs.textures[id] = { texture, view: texture.createView() };
		return id;
	}

	return {
	jsGpuActive: () => (gpuDevice ? 1 : 0),
	jsGpuInit: (wgslLen, wgslPtr) => {
		if (!gpuStatic)
			gpuCreateStatic(toJsString(wgslPtr, wgslLen, ctx.memory));
		// Draws that bind no texture sample id 0, which the default shader multiplies by.
		if (!gs.textures[0]) {
			const white = gpuDevice.createTexture({
				size: [1, 1, 1], format: 'rgba8unorm',
				usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST,
			});
			gpuDevice.queue.writeTexture({ texture: white }, new Uint8Array([255, 255, 255, 255]),
				{ bytesPerRow: 4, rowsPerImage: 1 }, [1, 1, 1]);
			gs.textures[0] = { texture: white, view: white.createView() };
		}
	},
	jsGpuCreateTexture: (width, height, channels, ptr) => createTexture(width, height, channels, ptr, 0),
	jsGpuUpdateTexture: (texture, x, y, width, height, channels, ptr) => {
		const entry = gs.textures[texture];
		if (!entry)
			return;
		const { data, bytesPerRow } = gpuPixels(channels, width, height, ptr, mem());
		gpuDevice.queue.writeTexture({ texture: entry.texture, origin: [x, y, 0] }, data,
			{ bytesPerRow, rowsPerImage: height }, [width, height, 1]);
	},
	jsGpuDestroyTexture: (texture) => {
		const entry = gs.textures[texture];
		if (!entry || texture === 0)
			return;
		entry.texture.destroy();
		delete gs.textures[texture];
	},
	jsGpuCreateTarget: (width, height, depth) => {
		const texture = gpuDevice.createTexture({
			size: [width, height, 1], format: 'rgba8unorm',
			usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.TEXTURE_BINDING
				| GPUTextureUsage.COPY_SRC | GPUTextureUsage.COPY_DST,
		});
		const depthTexture = gpuDevice.createTexture({
			size: [width, height, 1], format: 'depth24plus', usage: GPUTextureUsage.RENDER_ATTACHMENT,
		});
		const view = texture.createView();
		const id = gs.nextId++;
		// A pass samples this target's own texture only after another pass wrote it, so the
		// contract that a fresh target reads as transparent needs a clear of its own.
		const encoder = gpuDevice.createCommandEncoder();
		encoder.beginRenderPass({ colorAttachments: [{
			view, loadOp: 'clear', storeOp: 'store', clearValue: { r: 0, g: 0, b: 0, a: 0 },
		}]}).end();
		gpuDevice.queue.submit([encoder.finish()]);
		gs.textures[id] = { texture, view };
		gs.targets[id] = { view, depthView: depthTexture.createView(), depthTexture, width, height };
		return id;
	},
	jsGpuDestroyTarget: (target) => {
		const entry = gs.targets[target];
		if (!entry)
			return;
		entry.depthTexture.destroy();
		gs.textures[target].texture.destroy();
		delete gs.targets[target];
		delete gs.textures[target];
	},
	jsGpuCopyCanvasToTarget: (target, srcX, srcY, srcW, srcH, w, h) => {
		gpuWarnOnce('copyCanvas', 'copying the canvas into a render target is not implemented '
			+ '(WebGPU cannot scale or flip a texture-to-texture copy); the target is left as is');
	},
	jsGpuGeometry: (id, generation, vertexCount, posPtr, colPtr, uvPtr, matPtr, edgePtr, idxPtr, indexCount) => {
		let m = gs.models[id];
		if (!m)
			m = gs.models[id] = { generation: generation - 1, bufs: [], indexCount: 0 };
		if (m.generation === generation)
			return;
		m.generation = generation;
		m.vertexCount = vertexCount;
		m.indexCount = indexCount;
		const queue = gpuDevice.queue;
		const ptrs = [posPtr, colPtr, uvPtr, matPtr, edgePtr];
		for (let i = 0; i < 5; i++) {
			const buf = gpuGrowBuffer(m, 'buf' + i, Math.max(4, vertexCount * GPU_VERTEX_STRIDES[i]),
				GPUBufferUsage.VERTEX);
			m.bufs[i] = buf;
			if (vertexCount === 0)
				continue;
			// A vertex buffer's stride must be a multiple of 4, so the material byte widens to u32.
			if (i === 3) {
				const src = new Uint8Array(ctx.memory.buffer, ptrs[i], vertexCount);
				const wide = new Uint32Array(vertexCount);
				for (let v = 0; v < vertexCount; v++)
					wide[v] = src[v];
				queue.writeBuffer(buf, 0, wide);
				continue;
			}
			const len = vertexCount * GPU_VERTEX_STRIDES[i];
			queue.writeBuffer(buf, 0, new Uint8Array(ctx.memory.buffer, ptrs[i], len).slice());
		}
		const index = gpuGrowBuffer(m, 'index', Math.max(4, indexCount * 4), GPUBufferUsage.INDEX);
		if (indexCount > 0)
			queue.writeBuffer(index, 0, new Uint8Array(ctx.memory.buffer, idxPtr, indexCount * 4).slice());
	},
	jsGpuUniforms: (id, ptr, byteLength) => {
		if (byteLength === 0)
			return;
		let u = gs.uniforms[id];
		if (!u)
			u = gs.uniforms[id] = {};
		const before = u.buffer;
		const buffer = gpuGrowBuffer(u, 'buffer', byteLength, GPUBufferUsage.UNIFORM);
		if (buffer !== before)
			u.group = gpuDevice.createBindGroup({ layout: gpuStatic.uniformLayout, entries: [
				{ binding: 0, resource: { buffer, size: 256 } },
			]});
		gpuDevice.queue.writeBuffer(buffer, 0, new Uint8Array(ctx.memory.buffer, ptr, byteLength).slice());
	},
	jsGpuBeginPass: (target, clear, clearDepth, r, g, b, a, vpX, vpY, vpW, vpH, scX, scY, scW, scH) => {
		gpuEndPass();
		if (!gpuFrame)
			gpuFrame = { encoder: gpuDevice.createCommandEncoder(), pass: null, canvasView: null, depthCleared: {} };
		let view, depthView, width, height;
		const flip = target !== 0;
		if (flip) {
			const entry = gs.targets[target];
			if (!entry)
				return;
			({ view, depthView, width, height } = entry);
		} else {
			if (!gpuContext)
				return;
			if (!gpuFrame.canvasView)
				gpuFrame.canvasView = gpuContext.getCurrentTexture().createView();
			view = gpuFrame.canvasView;
			width = glCanvas.width;
			height = glCanvas.height;
			depthView = gpuCanvasDepthView(width, height);
		}
		// GL apps clear depth once a frame, so a target that was not asked to clear still starts
		// the frame cleared - loading an attachment this frame has not written is undefined.
		const firstTouch = !gpuFrame.depthCleared[target];
		gpuFrame.depthCleared[target] = true;
		gpuFrame.flip = flip;
		gpuFrame.pass = gpuFrame.encoder.beginRenderPass({
			colorAttachments: [{
				view, loadOp: clear ? 'clear' : 'load', storeOp: 'store',
				clearValue: { r, g, b, a },
			}],
			depthStencilAttachment: {
				view: depthView,
				depthLoadOp: (clearDepth || firstTouch) ? 'clear' : 'load',
				depthStoreOp: 'store',
				depthClearValue: 1,
			},
		});
		if (vpW > 0 && vpH > 0) {
			const [x, y, w, h] = gpuRect(vpX, vpY, vpW, vpH, width, height, flip);
			if (w > 0 && h > 0)
				gpuFrame.pass.setViewport(x, y, w, h, 0, 1);
		}
		if (scW > 0 && scH > 0) {
			const [x, y, w, h] = gpuRect(scX, scY, scW, scH, width, height, flip);
			gpuFrame.pass.setScissorRect(x, y, w, h);
		}
		gpuFrame.pass.setBindGroup(2, gpuStatic.flipGroups[flip ? 1 : 0]);
	},
	jsGpuDraw: (geometry, pipelineKey, texture, sampler, uniforms, uniformOffset, indexStart, indexCount, instances) => {
		const pass = gpuFrame && gpuFrame.pass;
		const m = gs.models[geometry];
		const u = gs.uniforms[uniforms];
		if (!pass || !m || !u || indexCount === 0 || m.vertexCount === 0)
			return;
		pass.setPipeline(gpuPipeline(pipelineKey));
		pass.setBindGroup(0, u.group, [uniformOffset]);
		pass.setBindGroup(1, textureGroup(texture, sampler));
		for (let i = 0; i < 5; i++)
			pass.setVertexBuffer(i, m.bufs[i]);
		pass.setIndexBuffer(m.index, 'uint32');
		pass.drawIndexed(indexCount, instances, indexStart, 0, 0);
	},
	jsGpuSubmit: () => {
		gpuEndPass();
		if (!gpuFrame)
			return;
		gpuDevice.queue.submit([gpuFrame.encoder.finish()]);
		gpuFrame = null;
	},
	};
}

// One graphics import set per instance: WebGL2 plus an inert jsGpu*, or - when a WebGPU device
// was granted - the real jsGpu* with the GL entry points stubbed to no-ops. The recorded command
// buffer never reaches them in that mode, but the wasm still imports them, so they must exist.
function makeGraphicsExports(ctx) {
	const glExports = makeOpenglExports(ctx);
	if (!gpuDevice)
		return { ...glExports, ...makeGpuExports(ctx) };
	const stubs = {};
	for (const name of Object.keys(glExports))
		stubs[name] = () => 0;
	return { ...stubs, ...makeGpuExports(ctx) };
}

///////////////////////////////////////////////////////////////////////////////
// Window

function makeWindowExports(ctx) {
	return {
	jsInitWindow: (windowPtr, canvasLen, canvasPtr, desiredAspect, antialias) =>
	{
		var canvas = document.getElementById(toJsString(canvasPtr, canvasLen, ctx.memory));
		glCanvas = canvas;
		canvas.oncontextmenu = () => false; // disable right click
		if (gpuDevice) {
			gpuContext = canvas.getContext("webgpu");
			gpuContext.configure({
				device: gpuDevice,
				format: gpuFormat,
				alphaMode: "opaque",
				usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.COPY_SRC,
			});
		} else {
			gl = canvas.getContext("webgl2", { antialias: !!antialias });
			if (!(gl instanceof WebGL2RenderingContext)) {
				console.error("Missing webgl2 support");
				return;
			}
		}

		// Some trial and error to get this right, not just on desktop but also when rotating
		// your phone to landscape and portrait all the while maximizing the available space
		// and choosing a good resolution
		function resize() {
			const dpr = Math.min(window.devicePixelRatio || 1, 2);
			const w = Math.max(1, Math.round(canvas.clientWidth * dpr));
			const h = Math.max(1, Math.round(canvas.clientHeight * dpr));
			if (canvas.width === w && canvas.height === h)
				return;
			canvas.width = w;
			canvas.height = h;
			ctx.wasm.exports.windowResize(windowPtr, w, h);
		}

		if (window.ResizeObserver)
			new ResizeObserver(resize).observe(canvas);
		window.addEventListener('resize', resize);
		window.addEventListener('orientationchange', resize);
		if (window.visualViewport)
			window.visualViewport.addEventListener('resize', resize);
		resize();

		canvas.ondragstart = () => false;
		canvas.addEventListener("mousedown", (evt) => { ctx.wasm.exports.windowClick(windowPtr, 1, evt.button); }, false);
		canvas.addEventListener("mouseup", (evt) => { ctx.wasm.exports.windowClick(windowPtr, 0, evt.button); }, false);
		canvas.addEventListener("wheel", (evt) => {
			// evt.deltaY is negative when scrolling up, positive when scrolling down
			// The absolute value is usually 120 per scroll step, but can also be 40 or even 3
			ctx.wasm.exports.windowMouseWheel(windowPtr, evt.deltaX < 0 ? -1 : 1, evt.deltaY < 0 ? -1 : 1);
			evt.preventDefault();
		}, { passive: false });

		// Mobile controls: every finger keeps a slot index for as long as it touches the canvas
		canvas.style.touchAction = "none";
		const touchSlots = new Map();
		const freeSlots = [7, 6, 5, 4, 3, 2, 1, 0];

		function sendTouches(evt, action) {
			evt.preventDefault();
			for (const touch of evt.changedTouches) {
				let slot = touchSlots.get(touch.identifier);
				if (slot === undefined) {
					if (action !== 1 || freeSlots.length === 0)
						continue;
					slot = freeSlots.pop();
					touchSlots.set(touch.identifier, slot);
				}
				const {x, y} = canvasPos(touch);
				ctx.wasm.exports.windowTouch(windowPtr, slot, x, y, action);
				if (action === 0) {
					touchSlots.delete(touch.identifier);
					freeSlots.push(slot);
				}
			}
		}

		canvas.addEventListener("touchstart", (evt) => sendTouches(evt, 1), { passive: false });
		canvas.addEventListener("touchmove", (evt) => sendTouches(evt, 2), { passive: false });
		canvas.addEventListener("touchend", (evt) => sendTouches(evt, 0), { passive: false });
		canvas.addEventListener("touchcancel", (evt) => sendTouches(evt, 0), { passive: false });

		const onKey = (evt, action) => {
			if (evt.keyCode && evt.target.id == "game-canvas") {
				// Give game ability to claim keypresses, to e.g. prevent space bar scrolling
				// TODO: use .key for physical key, .code for static character "Enter" ("KeyQ" is always top left)
				if (ctx.wasm.exports.windowOnKey(windowPtr, evt.keyCode, action) != 0) {
					evt.preventDefault();
				}
			}
			return false; // don't eat up the key
		}
		window.addEventListener("keydown", (evt) => onKey(evt, evt.repeat ? 2 : 1), false);
		window.addEventListener("keyup", (evt) => onKey(evt, 0), false);

		// Typed characters (text input). keydown reports physical keys; keypress carries the actual
		// character after layout/modifiers, which we forward as a code point so text fields get input.
		// evt.key is the whole character ("a", "€"), and length 1 rules out named keys like "Enter".
		window.addEventListener("keypress", (evt) => {
			if (evt.target.id == "game-canvas" && evt.key && [...evt.key].length === 1) {
				ctx.wasm.exports.windowChar(windowPtr, evt.key.codePointAt(0));
			}
		}, false);


		function canvasPos(evt) {
			const rect = canvas.getBoundingClientRect();
			return {
				x: (evt.clientX - rect.left) * (canvas.width / rect.width),
				y: (evt.clientY - rect.top) * (canvas.height / rect.height),
			};
		}

		// CSS pixels per backing-store pixel, so relative motion lands in the same space as canvasPos
		function canvasScale() {
			const rect = canvas.getBoundingClientRect();
			return rect.width > 0 ? canvas.width / rect.width : 1;
		}

		canvas.addEventListener('mousemove', (evt) => {
			if (document.pointerLockElement === canvas) {
				// Captured: report relative motion, which keeps flowing past the canvas edge
				const s = canvasScale();
				ctx.wasm.exports.windowMouseDelta(windowPtr, evt.movementX * s, evt.movementY * s);
				return;
			}
			const {x, y} = canvasPos(evt);
			ctx.wasm.exports.windowMouse(windowPtr, x, y);
		}, false);

		// Keep the D-side capture flag in sync when the user exits pointer lock (e.g. via Esc)
		document.addEventListener('pointerlockchange', () => {
			if (document.pointerLockElement !== canvas && ctx.wasm.exports.hookPointerLockChange)
				ctx.wasm.exports.hookPointerLockChange(windowPtr, 0);
		}, false);

		canvas.addEventListener('pointermove', (evt) => {
			if (evt.pointerType !== 'pen')
				return;
			const {x, y} = canvasPos(evt);
			ctx.wasm.exports.hookPenMove(x, y, evt.pressure);
		}, false);

		// When dragging the canvas, by default the browser renders a transparent
		// copy of the canvas on the cursor, which you don't want in games
		canvas.addEventListener('dragover', (evt) => { evt.preventDefault(); }, false);

		canvas.addEventListener('drop', (evt) => {
			evt.preventDefault();
			const ptr = ctx.wasm.exports.windowDropBuf();
			for (const file of evt.dataTransfer.files) {
				const written = wasmStoreJsString(file.name, ptr, 4096, ctx.memory);
				ctx.wasm.exports.hookFileDrop(windowPtr, written);
			}
		}, false);
	},
	jsSetMouseCapture: (windowPtr, on) => {
		if (!glCanvas)
			return;
		if (on) {
			// requestPointerLock only succeeds inside a user gesture; if the browser rejects it, clear
			// the D-side flag so the game retries on the next window_mouse_set (e.g. after a click).
			const p = glCanvas.requestPointerLock();
			if (p && p.catch)
				p.catch(() => ctx.wasm.exports.hookPointerLockChange(windowPtr, 0));
		} else if (document.pointerLockElement === glCanvas) {
			document.exitPointerLock();
		}
	},
	jsSetClipboard: (len, ptr) => {
		navigator.clipboard.writeText(toJsString(ptr, len, ctx.memory)).catch(() => {});
	},
	// Works from the game loop shortly after a click/tap thanks to transient user activation
	jsOpenUrl: (len, ptr) => {
		window.open(toJsString(ptr, len, ctx.memory), "_blank", "noopener");
	},
	jsRequestClipboard: () => {
		navigator.clipboard.readText().then(text => {
			const ptr = ctx.wasm.exports.windowClipBuf();
			const encoded = new TextEncoder().encode(text);
			const len = Math.min(encoded.length, 4096);
			new Uint8Array(ctx.memory.buffer, ptr, len).set(encoded.subarray(0, len));
			ctx.wasm.exports.hookClipboard(len);
		}).catch(() => ctx.wasm.exports.hookClipboard(0));
	},
	jsToggleFullscreen: () => {
		if (!glCanvas)
			return;
		if (!document.fullscreenElement)
			glCanvas.requestFullscreen();
		else
			document.exitFullscreen();
	},
	jsCloseWindow: () => {
		ctx.windowClosed = true;
		if (audioContext) {
			audioContext.close().catch((e) => console.warn('audio close failed', e));
			audioContext = undefined;
		}
		window.close();
	},
	jsLoopWindow: (windowPtr, fps, lockstep) => {
		const timestep = 1000 / fps;
		let accumulator = 0;
		let lastTime = performance.now();

		function loop(now) {
			if (ctx.windowClosed)
				return;

			// Lockstep: exactly one step per drawn frame
			let steps = 1;
			if (!lockstep) {
				let delta = now - lastTime;
				lastTime = now;

				// Avoid spiral of death
				if (delta > 100)
					delta = timestep;

				accumulator += delta;

				const maxSteps = 3;
				steps = 0;
				while (accumulator >= timestep && steps < maxSteps) {
					accumulator -= timestep;
					steps++;
				}
			}

			for (let i = 0; i < steps; i++) {
				try {
					ctx.wasm.exports.windowStep(windowPtr);
				} catch (err) {
					console.error(err);
					return;
				}
			}
			// Draw on the fixed step, not the display: a 120Hz phone fires rAF twice per frame.
			if (steps > 0)
				ctx.wasm.exports.windowDraw(windowPtr);
			requestAnimationFrame(loop);
		}
		requestAnimationFrame(loop);
	},
};
}

var mainCtx;

function makeCtx() {
	return {
		wasm: null,
		wasmModule: null,
		memory: null,
		glState: makeGlState(),
		gpuState: makeGpuState(),
		windowClosed: false,
		audioNode: null,
		// Null unless debughost.js is loaded and this instance is hosted by another.
		parent: null,
	};
}

// Bring a freshly instantiated module up to the point where the browser drives it. Shared-memory
// builds have passive data/TLS segments, so the main thread's TLS and the ctors (which also do
// the one-time memory init) must run before anything is called. _start runs the WASI arg path
// (args_get -> EntryPoint _start -> main), same as the CLI, and returns once the frame loop is
// scheduled - on wasm runLoop() does not block.
function startInstance(ctx) {
	const ex = ctx.wasm.exports;
	if (ex.__wasm_init_tls) ex.__wasm_init_tls(ex.mainTlsBase());
	if (ex.__wasm_call_ctors) ex.__wasm_call_ctors();
	ex._start();
}

// debughost.js is optional (see its header): without it a page runs one module and cannot host
// another, so a module importing env.dbg* will fail to instantiate.
function hasDebugHost() {
	return typeof makeDebugHostExports === 'function';
}

function makeEnvExports(ctx, windowFactory = makeWindowExports) {
	return {
		...makeSoundEngineExports(ctx),
		...makeMidiExports(ctx),
		...makeGamepadExports(ctx),
		...makeSaveDataExports(ctx),
		...makeGraphicsExports(ctx),
		...windowFactory(ctx),
	};
}

async function initWasm()
{
	const params = new URLSearchParams(location.search);
	const wasmFile = params.get('wasm') || 'main.wasm';

	listenDeviceMotion();
	setupMobileSession();

	// debughost.js, if the page included it, claims the params that configure hosting.
	const claimed = hasDebugHost() ? dbgConfigure(params) : [];
	// ?gpu=webgpu renders through the WebGPU backend instead of WebGL2. The device must exist
	// before the wasm is instantiated: jsGpuActive decides which backend Graphics builds.
	claimed.push('gpu', 'audio');
	if (params.get('gpu') === 'webgpu')
		await requestGpuDevice();

	// Forward URL params (other than wasm=XXX) to main
	for (const [name, value] of params) {
		if (name === 'wasm' || claimed.includes(name))
			continue;
		wasmArgs.push('-' + name + '=' + value);
		try {
			const resp = await fetch(value);
			if (resp.ok)
				fsReadFiles[value] = new Uint8Array(await resp.arrayBuffer());
		} catch (e) { /* not a fetchable file: passed through as a plain arg value */ }
	}

	mainCtx = makeCtx();
	const imports = { ...makeEnvExports(mainCtx), ...(hasDebugHost() ? makeDebugHostExports(mainCtx, wasmFile) : {}) };
	await loadWasm(wasmFile, imports, mainCtx);

	setStatus('starting...');
	startInstance(mainCtx);
	setStatus(null);
}

window.addEventListener('load', (event) => { initWasm() });

// Listen to 'reload' messages from devserver.py so `make` can refresh the page after building
// esbuild replaces DEBUG with a constant in release; the dev build copies this file
// raw, so guard the reference to avoid a ReferenceError when DEBUG is undefined.
if (typeof DEBUG !== 'undefined' && DEBUG) {
	function watchReload() {
		const ws = new WebSocket('ws://localhost:8765');
		ws.onopen = () => console.log("✅ WebSocket connected");
		ws.onerror = () => console.error("⚠️ WebSocket error");
		ws.onmessage = msg => {
			if (msg.data === 'reload') {
				location.replace(location.pathname + '?reload=' + Date.now());
			} else {
				console.log("unknown message " + msg.data);
			}
		};
	}
	watchReload();
}
